import React from "react";
import { Checkbox, Form, Input } from "antd";
import { SSWidget } from "../../../types";

interface Props {
    key: number;
    name: (string | number)[];
    widget: SSWidget;
}

export const WidgetsForm: React.FC<Props> = ({ key, name, widget }) => {
    return (
        <>
            <Form.Item noStyle name={[...name, "Name"]} label="Name">
                <Input type="hidden" />
            </Form.Item>
            <Form.Item noStyle name={[...name, "Label"]} label="Label">
                <Input type="hidden" />
            </Form.Item>
            <Form.Item name={[...name, "Enabled"]} label={widget.Label} valuePropName="checked">
                <Checkbox />
            </Form.Item>
        </>
    );
};
